import * as THREE from 'three';

/**
 * HD surface textures (generated by tools/gen-textures.py, all tileable): colour, normal and ORM maps
 * for terrain, roads, pavements and trees. Loaded once before the city is built; any file that fails
 * to load is replaced by a flat stand-in so the game still runs.
 */
export interface SurfaceSet {
  grass: THREE.Texture;
  grassN: THREE.Texture;
  dirt: THREE.Texture;
  dirtN: THREE.Texture;
  rock: THREE.Texture;
  rockN: THREE.Texture;
  macro: THREE.Texture;
  asphalt: THREE.Texture;
  asphaltN: THREE.Texture;
  asphaltORM: THREE.Texture;
  pave: THREE.Texture;
  paveN: THREE.Texture;
  paveORM: THREE.Texture;
  bark: THREE.Texture;
  barkN: THREE.Texture;
  leaves: THREE.Texture;
  needles: THREE.Texture;
  flowers: THREE.Texture;
  /** True when every file loaded (false means some stand-ins are in use). */
  complete: boolean;
}

const FILES: Record<Exclude<keyof SurfaceSet, 'complete'>, [string, 'color' | 'data', number]> = {
  grass: ['grass_c.jpg', 'color', 0x4f7a2c],
  grassN: ['grass_n.jpg', 'data', 0x8080ff],
  dirt: ['dirt_c.jpg', 'color', 0x6b5038],
  dirtN: ['dirt_n.jpg', 'data', 0x8080ff],
  rock: ['rock_c.jpg', 'color', 0x7a756c],
  rockN: ['rock_n.jpg', 'data', 0x8080ff],
  macro: ['macro.jpg', 'data', 0x808080],
  asphalt: ['asphalt_c.jpg', 'color', 0x343537],
  asphaltN: ['asphalt_n.jpg', 'data', 0x8080ff],
  asphaltORM: ['asphalt_orm.jpg', 'data', 0xffe000],
  pave: ['pave_c.jpg', 'color', 0x9a968e],
  paveN: ['pave_n.jpg', 'data', 0x8080ff],
  paveORM: ['pave_orm.jpg', 'data', 0xffe000],
  bark: ['bark_c.jpg', 'color', 0x5a3e2c],
  barkN: ['bark_n.jpg', 'data', 0x8080ff],
  leaves: ['leaves.png', 'color', 0x4a7a32],
  needles: ['needles_c.jpg', 'color', 0x2e4a26],
  flowers: ['flowers.png', 'color', 0xffffff],
};

let current: SurfaceSet | null = null;

/** The loaded set (null before `loadSurfaces` has finished). */
export function surfaces(): SurfaceSet | null {
  return current;
}

function solid(hex: number, alpha = 255): THREE.DataTexture {
  const t = new THREE.DataTexture(new Uint8Array([(hex >> 16) & 255, (hex >> 8) & 255, hex & 255, alpha]), 1, 1);
  t.needsUpdate = true;
  return t;
}

export async function loadSurfaces(maxAnisotropy = 8, base = './assets/tex/', timeoutMs = 25000): Promise<SurfaceSet> {
  const loader = new THREE.TextureLoader();
  const aniso = Math.min(8, maxAnisotropy);
  let complete = true;
  const entries = await Promise.all(
    (Object.keys(FILES) as (keyof typeof FILES)[]).map(async (key) => {
      const [file, kind, fallback] = FILES[key];
      let tex: THREE.Texture;
      try {
        tex = await Promise.race([
          loader.loadAsync(base + file),
          new Promise<never>((_, rej) => setTimeout(() => rej(new Error('timeout')), timeoutMs)),
        ]);
      } catch {
        complete = false;
        tex = solid(fallback, key === 'leaves' || key === 'flowers' ? 0 : 255);
      }
      tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
      tex.anisotropy = aniso;
      tex.colorSpace = kind === 'color' ? THREE.SRGBColorSpace : THREE.NoColorSpace;
      tex.needsUpdate = true;
      return [key, tex] as const;
    }),
  );
  current = { ...(Object.fromEntries(entries) as Omit<SurfaceSet, 'complete'>), complete };
  return current;
}

/** A copy of a surface texture with its own repeat (shares the image, so it costs no extra memory). */
export function repeated(t: THREE.Texture, x: number, y = x): THREE.Texture {
  const c = t.clone();
  c.repeat.set(x, y);
  c.needsUpdate = true;
  return c;
}
